package com.tihai.utils;
import org.springframework.stereotype.Service;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import javax.xml.stream.*;
@Service public class SigninStore {
 private final Path root;private final ObjectMapper json=new ObjectMapper();private Map<String,Object> settings;private Map<String,Map<String,Object>> records,locations;
 public SigninStore(){this(Paths.get("D:/tool/qita/SuperAutoStudy"));}public SigninStore(Path p){root=p;try{settings=read("config/signin-settings.json");records=(Map)read("data/signin/records.json");locations=(Map)read("data/signin/locations.json");settings.putIfAbsent("autoNormal",false);settings.putIfAbsent("courseKeys",new ArrayList<>());}catch(Exception e){throw new IllegalStateException("签到配置或记录无法读取，已停止写入以保留原文件",e);}}
 private Map<String,Object> read(String path)throws IOException{Path p=root.resolve(path);return Files.exists(p)?json.readValue(Files.readAllBytes(p),Map.class):new LinkedHashMap<>();}
 private void save(String path,Object data)throws IOException{Path p=root.resolve(path);Files.createDirectories(p.getParent());Path temp=p.resolveSibling(p.getFileName()+".new");Files.write(temp,json.writeValueAsBytes(data));try{Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING);}}
 private Map<String,Object> copy(Map<String,Object> m){return json.convertValue(m,Map.class);}
 private Map<String,Map<String,Object>> scopedSettings=new LinkedHashMap<>();
 private String settingsFile(){return AccountScope.scoped()?"config/accounts/"+AccountScope.id()+"/signin-settings.json":"config/signin-settings.json";}
 private Map<String,Object> currentSettings(){if(!AccountScope.scoped())return settings;String key=AccountScope.id();if(!scopedSettings.containsKey(key)){try{Map<String,Object> m=read(settingsFile());m.putIfAbsent("autoNormal",false);m.putIfAbsent("courseKeys",new ArrayList<>());scopedSettings.put(key,m);}catch(IOException e){throw new IllegalStateException("当前账号签到设置读取失败",e);}}return scopedSettings.get(key);}
 public synchronized Map<String,Object> settings(){return copy(currentSettings());}
 public synchronized void settings(boolean enabled,Collection<String> courseKeys)throws IOException{Set<String> keys=new LinkedHashSet<>();for(String key:courseKeys){if(!key.matches("[a-zA-Z0-9-]+"))throw new IOException("课程标识无效");keys.add(key);}Map<String,Object> m=currentSettings();m.put("autoNormal",enabled);m.put("courseKeys",new ArrayList<>(keys));save(settingsFile(),m);}
 public synchronized Map<String,Object> record(String id){Map<String,Object> m=records.get(id);return m==null?null:copy(m);}
 public synchronized boolean claim(String id,Map<String,Object> value)throws IOException{if(records.containsKey(id))return false;Map<String,Object> r=copy(value);r.put("state","signing");r.put("message","正在签到，尚未确认平台结果");r.put("claimed",true);r.put("updatedAt",java.time.LocalDateTime.now().toString());records.put(id,r);save("data/signin/records.json",records);return true;}
 public synchronized void result(String id,String state,String message)throws IOException{Map<String,Object> r=records.get(id);if(r==null)r=new LinkedHashMap<>();r.put("state",state);r.put("message",message);r.put("updatedAt",java.time.LocalDateTime.now().toString());records.put(id,r);save("data/signin/records.json",records);}
 public synchronized Map<String,Object> addLocation(String name,double latitude,double longitude,String address)throws IOException{validate(latitude,longitude);if(name==null||name.trim().isEmpty()||name.length()>100)throw new IOException("请输入1至100字的位置名称");if(address!=null&&address.length()>300)throw new IOException("位置说明过长");Map<String,Object> p=new LinkedHashMap<>();String id=UUID.randomUUID().toString();p.put("id",id);p.put("name",name.trim());p.put("latitude",latitude);p.put("longitude",longitude);p.put("address",address==null?"":address.trim());p.put("coordinateSystem","WGS84");locations.put(id,p);save("data/signin/locations.json",locations);return copy(p);}
 public static void validate(double latitude,double longitude)throws IOException{if(!Double.isFinite(latitude)||!Double.isFinite(longitude)||latitude < -90||latitude > 90||longitude < -180||longitude >180)throw new IOException("纬度应在-90至90，经度应在-180至180，且必须是有限数字");}
 public synchronized List<Map<String,Object>> locations(){List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> p:locations.values())out.add(copy(p));return out;}
 public synchronized void deleteLocation(String id)throws IOException{locations.remove(id);save("data/signin/locations.json",locations);}
 public synchronized byte[] exportGpx()throws Exception{StringWriter out=new StringWriter();XMLStreamWriter w=XMLOutputFactory.newFactory().createXMLStreamWriter(out);w.writeStartDocument("UTF-8","1.0");w.writeStartElement("gpx");w.writeDefaultNamespace("http://www.topografix.com/GPX/1/1");w.writeAttribute("version","1.1");w.writeAttribute("creator","StudentTong");for(Map<String,Object> p:locations.values()){w.writeStartElement("wpt");w.writeAttribute("lat",String.valueOf(p.get("latitude")));w.writeAttribute("lon",String.valueOf(p.get("longitude")));w.writeStartElement("name");w.writeCharacters(String.valueOf(p.get("name")));w.writeEndElement();w.writeStartElement("desc");w.writeCharacters(String.valueOf(p.get("address")));w.writeEndElement();w.writeEndElement();}w.writeEndElement();w.writeEndDocument();w.close();return out.toString().getBytes(StandardCharsets.UTF_8);}
 public synchronized int importGpx(byte[] input)throws Exception{if(input.length>2*1024*1024)throw new IOException("GPX文件不能超过2MB");String text=new String(input,StandardCharsets.UTF_8);if(text.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||text.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IOException("不支持含外部实体或DTD的GPX文件");XMLInputFactory factory=XMLInputFactory.newFactory();factory.setProperty(XMLInputFactory.SUPPORT_DTD,false);factory.setProperty("javax.xml.stream.isSupportingExternalEntities",false);XMLStreamReader r=factory.createXMLStreamReader(new ByteArrayInputStream(input));List<Map<String,Object>> parsed=new ArrayList<>();Map<String,Object> point=null;while(r.hasNext()){int event=r.next();if(event==XMLStreamConstants.START_ELEMENT){String n=r.getLocalName();if(Arrays.asList("wpt","trkpt","rtept").contains(n)){if(parsed.size()>=1000)throw new IOException("一次最多导入1000个位置");double lat=Double.parseDouble(r.getAttributeValue(null,"lat")),lon=Double.parseDouble(r.getAttributeValue(null,"lon"));validate(lat,lon);point=new LinkedHashMap<>();point.put("latitude",lat);point.put("longitude",lon);point.put("name","导入位置 "+(parsed.size()+1));point.put("address","");}else if(point!=null&&"name".equals(n)){String name=r.getElementText();if(name.length()>100)throw new IOException("位置名称过长");point.put("name",name);}else if(point!=null&&"desc".equals(n)){String desc=r.getElementText();point.put("address",desc.length()>300?desc.substring(0,300):desc);}}else if(event==XMLStreamConstants.END_ELEMENT&&point!=null&&Arrays.asList("wpt","trkpt","rtept").contains(r.getLocalName())){parsed.add(point);point=null;}}r.close();if(parsed.isEmpty())throw new IOException("未读取到GPX位置点");for(Map<String,Object> p:parsed){String id=UUID.randomUUID().toString();p.put("id",id);p.put("coordinateSystem","WGS84");locations.put(id,p);}save("data/signin/locations.json",locations);return parsed.size();}
}
